package ru.kryuch.krtg.searcher.helper;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import ru.kryuch.krtg.searcher.entity.ChatEntity;import ru.kryuch.krtg.searcher.entity.FolderEntity;import ru.kryuch.krtg.searcher.repository.ChatRepository;import ru.kryuch.krtg.searcher.repository.FolderRepository;import java.util.List;import java.util.Map;import java.util.function.Function;import java.util.stream.Collectors;import java.util.stream.StreamSupport;@Component@RequiredArgsConstructorpublic class FolderHelper {    private final FolderRepository folderRepository;    public Map<Integer, FolderEntity> getFolderMap(List<Integer> folderIds) {        return StreamSupport.stream(                        folderRepository.findAllById(folderIds).spliterator(),                        false                )                .collect(Collectors.toMap(                        FolderEntity::getId,                        Function.identity()                ));    }}